import * as THREE from './assets/three.module.js';
const canvas=document.querySelector('#sculpture');let paused=document.body.classList.contains('paused'),onscreen=false,raf=0,t=0,scroll=0,mouse={x:0,y:0};
try{
const renderer=new THREE.WebGLRenderer({canvas,alpha:true,antialias:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));renderer.outputColorSpace=THREE.SRGBColorSpace;
const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(36,1,.1,40);camera.position.set(0,.2,8.4);const core=new THREE.Group();scene.add(core);scene.add(new THREE.AmbientLight(0xb4c9ec,1.8));const light=new THREE.DirectionalLight(0xd9f6ff,3);light.position.set(2,4,5);scene.add(light);const rim=new THREE.DirectionalLight(0x4d8eff,2);rim.position.set(-3,1,-2);scene.add(rim);
// Two connected cerebral lobes form the neural graph above the processor.
const vertices=[];for(let side of [-1,1])for(let i=0;i<92;i++){const y=1-2*(i+.5)/92,a=i*Math.PI*(3-Math.sqrt(5)),s=Math.sqrt(1-y*y);vertices.push(new THREE.Vector3(side*.51+Math.cos(a)*s*.76,y*1.03+.65,Math.sin(a)*s*.82))}
const lineVertices=[],edges=[];for(let i=0;i<vertices.length;i++)for(let j=i+1;j<vertices.length;j++){const d=vertices[i].distanceTo(vertices[j]);if(d<.49&&d>.14){lineVertices.push(...vertices[i].toArray(),...vertices[j].toArray());edges.push([vertices[i],vertices[j]])}}
const wireGeo=new THREE.BufferGeometry();wireGeo.setAttribute('position',new THREE.Float32BufferAttribute(lineVertices,3));const wires=new THREE.LineSegments(wireGeo,new THREE.LineBasicMaterial({color:0x7ab9df,transparent:true,opacity:.36}));core.add(wires);
const nodeGeometry=new THREE.SphereGeometry(.025,8,6),nodeMaterial=new THREE.MeshBasicMaterial({color:0xc5edff}),nodes=new THREE.InstancedMesh(nodeGeometry,nodeMaterial,vertices.length);const dummy=new THREE.Object3D();vertices.forEach((p,i)=>{dummy.position.copy(p);dummy.updateMatrix();nodes.setMatrixAt(i,dummy.matrix)});core.add(nodes);
const chipMaterial=new THREE.MeshStandardMaterial({color:0x1b3049,metalness:.65,roughness:.3});const chip=new THREE.Mesh(new THREE.BoxGeometry(1.85,.2,1.45),chipMaterial);chip.position.y=-1.05;core.add(chip);const chipOutline=new THREE.LineSegments(new THREE.EdgesGeometry(chip.geometry),new THREE.LineBasicMaterial({color:0x9cbed7}));chip.add(chipOutline);
const labelCanvas=document.createElement('canvas');labelCanvas.width=512;labelCanvas.height=384;const lc=labelCanvas.getContext('2d');lc.fillStyle='#101d32';lc.fillRect(0,0,512,384);lc.strokeStyle='#668eb2';lc.lineWidth=3;lc.strokeRect(18,18,476,348);lc.fillStyle='#d3ebff';lc.font='bold 140px sans-serif';lc.textAlign='center';lc.fillText('AI',256,235);lc.font='20px monospace';lc.fillStyle='#799bbd';lc.fillText('INFERENCE / QUALITY',256,305);const chipTexture=new THREE.CanvasTexture(labelCanvas);chipTexture.colorSpace=THREE.SRGBColorSpace;const face=new THREE.Mesh(new THREE.PlaneGeometry(1.7,1.3),new THREE.MeshBasicMaterial({map:chipTexture}));face.rotation.x=-Math.PI/2;face.position.y=-.94;core.add(face);
for(let side of [-1,1])for(let i=0;i<9;i++){const pin=new THREE.Mesh(new THREE.BoxGeometry(.18,.035,.048),new THREE.MeshStandardMaterial({color:0x98b9d8,metalness:.8,roughness:.3}));pin.position.set(side*1.02,-1.03,(i-4)*.13);core.add(pin)}
for(let i=0;i<11;i++){const x=(i-5)*.14;const geo=new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(x,-.94,0),new THREE.Vector3(x,-.5,0),new THREE.Vector3(x*.7,-.25,.1)]);core.add(new THREE.Line(geo,new THREE.LineBasicMaterial({color:0x519bc7,transparent:true,opacity:.35})))}
const packets=Array.from({length:18},(_,i)=>{const mesh=new THREE.Mesh(new THREE.SphereGeometry(.045,10,8),new THREE.MeshBasicMaterial({color:i%3===0?0xffffff:0x70d2ee}));core.add(mesh);return{mesh,edge:edges[(i*31)%edges.length],offset:i/18}});
const ring=new THREE.Mesh(new THREE.TorusGeometry(2.06,.006,6,160),new THREE.MeshBasicMaterial({color:0x7798bd,transparent:true,opacity:.25}));ring.rotation.x=1.35;ring.position.y=-1.3;core.add(ring);
function render(){core.rotation.y=-.15+scroll*.85+Math.sin(t*.14)*.15+mouse.x*.18;core.rotation.x=.2+scroll*.08+mouse.y*.08;core.position.y=Math.sin(t*.5)*.05;wires.material.opacity=.27+Math.sin(t*.7)*.07;packets.forEach(p=>p.mesh.position.lerpVectors(p.edge[0],p.edge[1],(t*.28+p.offset+scroll*.5)%1));renderer.render(scene,camera)}
function resize(){const r=canvas.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();render()}new ResizeObserver(resize).observe(canvas);
let last=0;function tick(now){raf=0;if(paused||!onscreen||document.hidden)return;t+=Math.min((now-last)/1000,.04);last=now;render();raf=requestAnimationFrame(tick)}function start(){if(!raf&&!paused&&onscreen&&!document.hidden){last=performance.now();raf=requestAnimationFrame(tick)}}addEventListener('portfolio-scroll',e=>{if(paused)return;scroll=e.detail.dimension;render()});addEventListener('motionchange',e=>{paused=e.detail.paused;if(paused){cancelAnimationFrame(raf);raf=0;render()}else start()});document.addEventListener('visibilitychange',start);new IntersectionObserver(e=>{onscreen=e[0].isIntersecting;start()}).observe(canvas);canvas.addEventListener('pointermove',e=>{if(paused||e.pointerType==='touch')return;const r=canvas.getBoundingClientRect();mouse.x=(e.clientX-r.left)/r.width-.5;mouse.y=(e.clientY-r.top)/r.height-.5});canvas.addEventListener('pointerleave',()=>{mouse.x=0;mouse.y=0});canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();cancelAnimationFrame(raf);canvas.parentElement.classList.remove('webgl-ready')});resize();canvas.parentElement.classList.add('webgl-ready');
}catch(error){console.warn('3D neural core unavailable; showing static AI core.');}
